"""Импорт банковских выписок.

Поддерживаются три формата (колонки ищутся по названию без учёта регистра
и краевых пробелов, порядок произвольный, лишние колонки игнорируются):

    nova         date,amount,description        (разделитель ",")
    sfera        Дата;Сумма;Описание            (разделитель ";")
    sfera_split  Дата;Описание;Приход;Расход    (разделитель ";")
"""

from __future__ import annotations

import csv
import dataclasses
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from collections.abc import Callable, Iterator
from dataclasses import dataclass

from ledger.clock import Clock, SystemClock
from ledger.errors import (
    StatementError,
    StatementRowError,
    UnknownFormatError,
    ValidationError,
)
from ledger.models import Transaction, parse_amount
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

_SFERA_DATE = re.compile(r"\d{2}\.\d{2}\.\d{4}")
_SFERA_AMOUNT = re.compile(r"[+-]?\d+(,\d{1,2})?")
_ZERO_AMOUNT = re.compile(r"0+(,0{1,2})?")
_THOUSANDS = str.maketrans("", "", "   ")


@dataclass(frozen=True)
class RowError:
    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError]


class _RowProblem(Exception):
