_FORMATS: dict[str, tuple[str, dict[str, str], Callable]] = {
    "nova": (",", {"date": "date", "amount": "amount", "description": "description"}, _parse_nova),
    "sfera": (";", {"date": "дата", "amount": "сумма", "description": "описание"}, _parse_sfera),
    "sfera_split": (
        ";",
        {"date": "дата", "description": "описание", "income": "приход", "expense": "расход"},
        _parse_sfera_split,
    ),
}
# при неоднозначности (есть и «Сумма», и «Приход»/«Расход») побеждает sfera
_DETECT_ORDER = ("nova", "sfera", "sfera_split")


def _decode(path: str | os.PathLike[str]) -> tuple[str, str]:
    with open(path, "rb") as fh:
        data = fh.read()
    try:
        return data.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return data.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise UnknownFormatError("file is neither utf-8 nor cp1251") from exc


def _header_columns(text: str, fmt: str) -> dict[str, int] | None:
    """Индексы обязательных колонок формата в заголовке или None."""
    delimiter, required, _ = _FORMATS[fmt]
    first = next(csv.reader(io.StringIO(text, newline=""), delimiter=delimiter), None)
    if not first:
        return None
    names: dict[str, int] = {}
    for idx, name in enumerate(first):
        names.setdefault(name.strip().casefold(), idx)
    if any(name not in names for name in required.values()):
        return None
    return {key: names[name] for key, name in required.items()}


def _resolve(text: str, fmt: str | None) -> tuple[str, dict[str, int]]:
    if fmt is not None and fmt not in _FORMATS:
        raise ValueError(f"unknown format {fmt!r}")
    if not text.strip():
        raise UnknownFormatError("empty file")
    for name in (fmt,) if fmt else _DETECT_ORDER:
        cols = _header_columns(text, name)
        if cols is not None:
            return name, cols
    if fmt:
        raise UnknownFormatError(f"header does not match format {fmt!r}", line_no=1)
    raise UnknownFormatError("unrecognized header", line_no=1)


def detect_format(path: str | os.PathLike[str]) -> str:
    """Определяет формат выписки по заголовку: "nova", "sfera" или "sfera_split"."""
    text, _ = _decode(path)
    return _resolve(text, None)[0]


def _records(text: str, delimiter: str) -> Iterator[tuple[int, list[str]]]:
    """Записи после заголовка с номером первой физической строки каждой."""
    state = {"n": 0, "start": None}

    def lines() -> Iterator[str]:
        for line in io.StringIO(text, newline=""):
            state["n"] += 1
            if state["start"] is None and line.strip("\r\n"):
                state["start"] = state["n"]
            yield line

    reader = csv.reader(lines(), delimiter=delimiter)
    next(reader)  # заголовок
    state["start"] = None
    for row in reader:
        start, state["start"] = state["start"], None
        if not row or start is None:
            continue
        yield start, row


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store и возвращает отчёт.

    Дубль — только строка, которой соответствует операция, уже бывшая в store
    до загрузки (по количеству); одинаковые строки внутри файла — разные операции.
    """
    clock = clock or SystemClock()
    imported_at = clock.now()
    text, encoding = _decode(path)
    fmt, cols = _resolve(text, fmt)
    delimiter, _, parse = _FORMATS[fmt]
    need = max(cols.values()) + 1

    existing = Counter(
        (t.date, t.amount, normalize_description(t.description)) for t in store.all()
    )
    new: list[Transaction] = []
    errors: list[RowError] = []
    duplicates = 0
    for line_no, row in _records(text, delimiter):
        if all(not f.strip() for f in row):
            continue
        try:
            if len(row) < need:
                raise _RowProblem("not enough fields")
            date, amount, description = parse(row, cols)
            tx = Transaction(date=date, amount=amount, description=description, imported_at=imported_at)
        except (_RowProblem, ValidationError) as exc:
            message = exc.args[0] if isinstance(exc, _RowProblem) else str(exc)
            if strict:
                raise StatementRowError(message, line_no=line_no) from exc
            errors.append(RowError(line_no, message))
            continue
        key = (tx.date, tx.amount, normalize_description(tx.description))
        if existing[key] > 0:
            existing[key] -= 1
            duplicates += 1
            continue
        if categorizer is not None:
            category = categorizer.categorize(tx)
            if category is not None:
                tx = dataclasses.replace(tx, category=category)
        new.append(tx)

    if new:
        store.add_many(new)
    logger.info("imported %d transactions from %s (%d duplicates)", len(new), path, duplicates)
    return ImportResult(fmt, encoding, len(new), duplicates, errors)


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Импортирует выписку «Новы» в store и возвращает число добавленных транзакций."""
    result = import_statement(
        path, store, fmt="nova", strict=True, categorizer=categorizer, clock=clock
    )
    return result.added
